function Component({ config = {} }) {
  var buttonText = config?.buttonText || 'Open Modal';
  var modalTitle = config?.modalTitle || 'Confirm Action';
  var modalContent = config?.modalContent || 'Are you sure you want to proceed with this action?';
  var confirmText = config?.confirmText || 'Confirm';
  var cancelText = config?.cancelText || 'Cancel';
  var modalWidth = parseInt(config?.modalWidth || '420');
  var transitionDuration = parseInt(config?.transitionDuration || '300');
  var enableBackdropBlur = config?.enableBackdropBlur !== false;

  var backgroundColor = config?.backgroundColor || '#FAFAFA';
  var buttonBackground = config?.buttonBackground || '#18181B';
  var buttonTextColor = config?.buttonTextColor || '#FFFFFF';
  var modalBackground = config?.modalBackground || '#FFFFFF';
  var overlayColor = config?.overlayColor || 'rgba(0,0,0,0.5)';
  var titleColor = config?.titleColor || '#18181B';
  var contentColor = config?.contentColor || '#52525B';
  var confirmButtonColor = config?.confirmButtonColor || '#18181B';
  var cancelButtonColor = config?.cancelButtonColor || '#71717A';
  var borderColor = config?.borderColor || '#E4E4E7';

  var titleFontSize = parseInt(config?.titleFontSize || '20');
  var contentFontSize = parseInt(config?.contentFontSize || '15');
  var buttonFontSize = parseInt(config?.buttonFontSize || '14');
  var containerPadding = parseInt(config?.containerPadding || '60');

  var _isOpen = React.useState(false);
  var isOpen = _isOpen[0];
  var setIsOpen = _isOpen[1];

  var _buttonHovered = React.useState(false);
  var buttonHovered = _buttonHovered[0];
  var setButtonHovered = _buttonHovered[1];

  var _confirmHovered = React.useState(false);
  var confirmHovered = _confirmHovered[0];
  var setConfirmHovered = _confirmHovered[1];

  var _cancelHovered = React.useState(false);
  var cancelHovered = _cancelHovered[0];
  var setCancelHovered = _cancelHovered[1];

  React.useEffect(function() {
    var handleEscape = function(e) {
      if (e.key === 'Escape' && isOpen) {
        setIsOpen(false);
      }
    };

    window.addEventListener('keydown', handleEscape);
    return function() { window.removeEventListener('keydown', handleEscape); };
  }, [isOpen]);

  React.useEffect(function() {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return function() { document.body.style.overflow = ''; };
  }, [isOpen]);

  var openModal = function() { setIsOpen(true); };
  var closeModal = function() { setIsOpen(false); };

  var handleOverlayClick = function(e) {
    if (e.target === e.currentTarget) {
      closeModal();
    }
  };

  var handleConfirm = function() {
    closeModal();
  };

  return React.createElement('div', {
    className: 'modal-component',
    style: {
      backgroundColor: backgroundColor,
      padding: containerPadding + 'px',
      minHeight: '300px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center'
    }
  }, [
    React.createElement('button', {
      key: 'trigger',
      onClick: openModal,
      onMouseEnter: function() { setButtonHovered(true); },
      onMouseLeave: function() { setButtonHovered(false); },
      style: {
        padding: '14px 28px',
        fontSize: buttonFontSize + 'px',
        fontWeight: '500',
        color: buttonTextColor,
