        backgroundColor: overlayColor,
        backdropFilter: enableBackdropBlur ? 'blur(4px)' : 'none',
        WebkitBackdropFilter: enableBackdropBlur ? 'blur(4px)' : 'none',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 1000,
        opacity: isOpen ? 1 : 0,
        visibility: isOpen ? 'visible' : 'hidden',
        transition: 'all ' + transitionDuration + 'ms ease'
      }
    }, React.createElement('div', {
      style: {
        backgroundColor: modalBackground,
        borderRadius: '12px',
        width: modalWidth + 'px',
        maxWidth: '90vw',
        maxHeight: '90vh',
        overflow: 'auto',
        boxShadow: '0 20px 60px rgba(0,0,0,0.2)',
        transform: isOpen ? 'scale(1) translateY(0)' : 'scale(0.95) translateY(10px)',
        opacity: isOpen ? 1 : 0,
        transition: 'all ' + transitionDuration + 'ms cubic-bezier(0.4, 0, 0.2, 1)'
      },
      role: 'dialog',
      'aria-modal': 'true',
      'aria-labelledby': 'modal-title'
    }, [
      React.createElement('div', {
        key: 'header',
        style: {
          padding: '24px 24px 0 24px'
        }
      }, [
        React.createElement('div', {
          key: 'title-row',
          style: {
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            marginBottom: '16px'
          }
        }, [
          React.createElement('h2', {
            key: 'title',
            id: 'modal-title',
            style: {
              fontSize: titleFontSize + 'px',
              fontWeight: '500',
              color: titleColor,
              margin: 0,
              fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
            }
          }, modalTitle),

          React.createElement('button', {
            key: 'close',
            onClick: closeModal,
            'aria-label': 'Close modal',
            style: {
              width: '32px',
              height: '32px',
              borderRadius: '6px',
              border: 'none',
              backgroundColor: 'transparent',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: '#A1A1AA',
              transition: 'all 150ms ease'
            },
            onMouseEnter: function(e) { e.target.style.backgroundColor = '#F4F4F5'; },
            onMouseLeave: function(e) { e.target.style.backgroundColor = 'transparent'; }
          }, React.createElement('svg', {
            width: 18,
            height: 18,
            viewBox: '0 0 18 18',
            fill: 'none'
          }, React.createElement('path', {
            d: 'M13.5 4.5L4.5 13.5M4.5 4.5L13.5 13.5',
            stroke: 'currentColor',
            strokeWidth: '1.5',
            strokeLinecap: 'round'
          })))
        ]),

        React.createElement('p', {
          key: 'content',
          style: {
            fontSize: contentFontSize + 'px',
            color: contentColor,
            lineHeight: 1.6,
            margin: 0,
            fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
          }
        }, modalContent)
      ]),

      React.createElement('div', {
        key: 'footer',
        style: {
          padding: '24px',
          display: 'flex',
          gap: '12px',
          justifyContent: 'flex-end',
          borderTop: '1px solid ' + borderColor,
          marginTop: '24px'
        }
      }, [
        React.createElement('button', {
          key: 'cancel',
          onClick: closeModal,
          onMouseEnter: function() { setCancelHovered(true); },
          onMouseLeave: function() { setCancelHovered(false); },
          style: {
            padding: '10px 20px',
            fontSize: buttonFontSize + 'px',
            fontWeight: '500',
            color: cancelButtonColor,
            backgroundColor: cancelHovered ? '#F4F4F5' : 'transparent',
            border: '1px solid ' + borderColor,
            borderRadius: '6px',
            cursor: 'pointer',
            fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
            transition: 'all 150ms ease'
          }
        }, cancelText),

        React.createElement('button', {
          key: 'confirm',
          onClick: handleConfirm,
          onMouseEnter: function() { setConfirmHovered(true); },
          onMouseLeave: function() { setConfirmHovered(false); },
          style: {
            padding: '10px 20px',
            fontSize: buttonFontSize + 'px',
            fontWeight: '500',
            color: '#FFFFFF',
            backgroundColor: confirmHovered ? '#27272A' : confirmButtonColor,
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
            transition: 'all 150ms ease'
          }
        }, confirmText)
      ])
    ]))
  ]);
}

