function Component({ config = {} }) {
  var triggerText = config?.triggerText || 'Hover over me';
  var tooltipContent = config?.tooltipContent || 'This is helpful information';
  var position = config?.position || 'top';
  var triggerStyle = config?.triggerStyle || 'text';
  var showArrow = config?.showArrow !== false;
  var maxWidth = parseInt(config?.maxWidth || '240');
  var delay = parseInt(config?.delay || '200');
  var transitionDuration = parseInt(config?.transitionDuration || '200');

  var backgroundColor = config?.backgroundColor || '#FFFFFF';
  var triggerColor = config?.triggerColor || '#3F3F46';
  var triggerHoverColor = config?.triggerHoverColor || '#18181B';
  var tooltipBackground = config?.tooltipBackground || '#18181B';
  var tooltipTextColor = config?.tooltipTextColor || '#FFFFFF';
  var borderColor = config?.borderColor || '#E4E4E7';

  var triggerFontSize = parseInt(config?.triggerFontSize || '15');
  var tooltipFontSize = parseInt(config?.tooltipFontSize || '13');
  var containerPadding = parseInt(config?.containerPadding || '80');

