  var isVisible = _isVisible[0];
  var setIsVisible = _isVisible[1];

  var _isHovered = React.useState(false);
  var isHovered = _isHovered[0];
  var setIsHovered = _isHovered[1];

  var timeoutRef = React.useRef(null);

  var handleMouseEnter = function() {
    setIsHovered(true);
    timeoutRef.current = setTimeout(function() {
      setIsVisible(true);
    }, delay);
  };

  var handleMouseLeave = function() {
    setIsHovered(false);
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    setIsVisible(false);
  };

  React.useEffect(function() {
    return function() {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  var getTooltipPosition = function() {
    var base = {
      position: 'absolute',
      zIndex: 100
    };

    switch (position) {
      case 'top':
        base.bottom = '100%';
        base.left = '50%';
        base.transform = isVisible ? 'translateX(-50%) translateY(-8px)' : 'translateX(-50%) translateY(0)';
        break;
      case 'bottom':
        base.top = '100%';
        base.left = '50%';
        base.transform = isVisible ? 'translateX(-50%) translateY(8px)' : 'translateX(-50%) translateY(0)';
        break;
      case 'left':
        base.right = '100%';
        base.top = '50%';
        base.transform = isVisible ? 'translateY(-50%) translateX(-8px)' : 'translateY(-50%) translateX(0)';
        break;
      case 'right':
        base.left = '100%';
        base.top = '50%';
        base.transform = isVisible ? 'translateY(-50%) translateX(8px)' : 'translateY(-50%) translateX(0)';
        break;
      default:
        base.bottom = '100%';
        base.left = '50%';
        base.transform = isVisible ? 'translateX(-50%) translateY(-8px)' : 'translateX(-50%) translateY(0)';
    }

    return base;
  };

  var getArrowStyle = function() {
    var arrowSize = 6;
    var base = {
      position: 'absolute',
      width: 0,
      height: 0,
      borderStyle: 'solid'
    };

    switch (position) {
      case 'top':
        base.top = '100%';
        base.left = '50%';
        base.transform = 'translateX(-50%)';
        base.borderWidth = arrowSize + 'px ' + arrowSize + 'px 0 ' + arrowSize + 'px';
        base.borderColor = tooltipBackground + ' transparent transparent transparent';
        break;
      case 'bottom':
        base.bottom = '100%';
        base.left = '50%';
        base.transform = 'translateX(-50%)';
        base.borderWidth = '0 ' + arrowSize + 'px ' + arrowSize + 'px ' + arrowSize + 'px';
        base.borderColor = 'transparent transparent ' + tooltipBackground + ' transparent';
        break;
      case 'left':
        base.left = '100%';
        base.top = '50%';
        base.transform = 'translateY(-50%)';
        base.borderWidth = arrowSize + 'px 0 ' + arrowSize + 'px ' + arrowSize + 'px';
        base.borderColor = 'transparent transparent transparent ' + tooltipBackground;
        break;
      case 'right':
        base.right = '100%';
        base.top = '50%';
        base.transform = 'translateY(-50%)';
        base.borderWidth = arrowSize + 'px ' + arrowSize + 'px ' + arrowSize + 'px 0';
