function Component({ config = {} }) {
  const [isOpen, setIsOpen] = React.useState(false);
  const modalRef = React.useRef(null);
  const overlayRef = React.useRef(null);
  const previousFocusRef = React.useRef(null);
  const firstFocusableRef = React.useRef(null);
  const lastFocusableRef = React.useRef(null);

  const closeOnOverlayClick = config?.closeOnOverlayClick !== false;
  const closeOnEscape = config?.closeOnEscape !== false;
  const showCloseButton = config?.showCloseButton !== false;
  const animationDuration = parseInt(config?.animationDuration || '250');

  // Modal size mapping
  const modalSizes = {
    small: '400px',
    medium: '600px',
    large: '800px'
  };

  const modalMaxWidth = modalSizes[config?.modalSize || 'medium'];

  // PATTERN 1: Direct DOM animation for modal entrance/exit
  const openModal = React.useCallback(() => {
    previousFocusRef.current = document.activeElement;
    setIsOpen(true);

    // Prevent body scroll
    document.body.style.overflow = 'hidden';

    // Animate overlay and modal
    requestAnimationFrame(() => {
      if (overlayRef.current) {
        overlayRef.current.animate([
          { opacity: 0 },
          { opacity: 1 }
        ], {
          duration: animationDuration,
          easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
          fill: 'forwards'
        });
      }

      if (modalRef.current) {
        modalRef.current.animate([
          { opacity: 0, transform: 'scale(0.95) translateY(-20px)' },
          { opacity: 1, transform: 'scale(1) translateY(0)' }
        ], {
          duration: animationDuration,
          easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
          fill: 'forwards'
        });
      }
    });
  }, [animationDuration]);

  const closeModal = React.useCallback(() => {
    if (overlayRef.current && modalRef.current) {
      overlayRef.current.animate([
        { opacity: 1 },
        { opacity: 0 }
      ], {
        duration: animationDuration,
        easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
        fill: 'forwards'
      });

      modalRef.current.animate([
        { opacity: 1, transform: 'scale(1) translateY(0)' },
        { opacity: 0, transform: 'scale(0.95) translateY(-20px)' }
      ], {
        duration: animationDuration,
        easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
        fill: 'forwards'
      }).onfinish = () => {
        setIsOpen(false);
        document.body.style.overflow = '';

        // Restore focus
        if (previousFocusRef.current) {
          previousFocusRef.current.focus();
        }
      };
    }
  }, [animationDuration]);

  // Focus trap
  React.useEffect(() => {
    if (!isOpen) return;

    const focusableElements = modalRef.current?.querySelectorAll(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    );

    if (focusableElements && focusableElements.length > 0) {
      firstFocusableRef.current = focusableElements[0];
      lastFocusableRef.current = focusableElements[focusableElements.length - 1];

      // Focus first element
      setTimeout(() => firstFocusableRef.current?.focus(), animationDuration);
    }
  }, [isOpen, animationDuration]);

  // Keyboard handlers
  React.useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e) => {
      // Escape key
      if (e.key === 'Escape' && closeOnEscape) {
        closeModal();
      }

      // Tab key (focus trap)
      if (e.key === 'Tab') {
        if (e.shiftKey) {
          // Shift + Tab
          if (document.activeElement === firstFocusableRef.current) {
            e.preventDefault();
            lastFocusableRef.current?.focus();
          }
        } else {
          // Tab
          if (document.activeElement === lastFocusableRef.current) {
            e.preventDefault();
            firstFocusableRef.current?.focus();
          }
        }
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, closeModal, closeOnEscape]);

  const styles = {
    container: {
      width: '100%',
      minHeight: '100vh',
      padding: '48px 24px',
      backgroundColor: config?.backgroundColor || '#FAFAFA',
      fontFamily: config?.fontFamily || 'Inter, -apple-system, system-ui, sans-serif',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center'
    },
    triggerButton: {
      padding: '14px 32px',
      fontSize: '16px',
      fontWeight: '500',
      color: '#FFFFFF',
      backgroundColor: config?.primaryButtonColor || '#1A1A1A',
      border: 'none',
      borderRadius: config?.borderRadius || '12px',
      cursor: 'pointer',
      transition: `all ${animationDuration}ms cubic-bezier(0.4, 0, 0.2, 1)`,
      outline: 'none'
    },
    overlay: {
      position: 'fixed',
      top: '0',
      left: '0',
      right: '0',
      bottom: '0',
      backgroundColor: config?.overlayColor || 'rgba(0,0,0,0.5)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '24px',
      zIndex: '9999',
      opacity: 0,
