function Component({ config = {} }) {
  const [toasts, setToasts] = React.useState([]);
  const toastIdCounter = React.useRef(0);
  const timersRef = React.useRef({});
  const swipeStateRef = React.useRef({});

  const position = config?.position || 'top-right';
  const maxToasts = parseInt(config?.maxToasts || '5');
  const defaultDuration = parseInt(config?.defaultDuration || '5000');
  const enableSwipeDismiss = config?.enableSwipeDismiss !== false;
  const showProgressBar = config?.showProgressBar !== false;
  const pauseOnHover = config?.pauseOnHover !== false;
  const animationDuration = parseInt(config?.animationDuration || '300');
  const swipeThreshold = parseInt(config?.swipeThreshold || '100');
  const demoMode = config?.demoMode !== false;

  // Add toast function
  const addToast = React.useCallback((type, title, message, duration = defaultDuration) => {
    const id = toastIdCounter.current++;
    const newToast = { id, type, title, message, duration, createdAt: Date.now() };

    setToasts(prev => {
      const updated = [newToast, ...prev];
      return updated.slice(0, maxToasts);
    });

    // Start auto-dismiss timer
    if (duration > 0) {
      timersRef.current[id] = setTimeout(() => {
        removeToast(id);
      }, duration);
    }
  }, [defaultDuration, maxToasts]);

  // Remove toast function
  const removeToast = React.useCallback((id) => {
    const element = document.querySelector(`[data-toast-id="${id}"]`);

    if (element) {
      // PATTERN 1: Direct DOM exit animation
      element.animate([
        { opacity: 1, transform: 'translateX(0) scale(1)' },
        { opacity: 0, transform: 'translateX(100px) scale(0.9)' }
      ], {
        duration: animationDuration,
        easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
        fill: 'forwards'
      }).onfinish = () => {
        setToasts(prev => prev.filter(t => t.id !== id));
        clearTimeout(timersRef.current[id]);
        delete timersRef.current[id];
      };
    } else {
      setToasts(prev => prev.filter(t => t.id !== id));
      clearTimeout(timersRef.current[id]);
      delete timersRef.current[id];
    }
  }, [animationDuration]);

  // Demo mode - add sample toasts
  React.useEffect(() => {
    if (!demoMode) return;

    const demos = [
      { type: 'success', title: 'Success', message: 'Your changes have been saved successfully.', delay: 0 },
      { type: 'error', title: 'Error', message: 'Failed to connect to the server. Please try again.', delay: 1000 },
      { type: 'warning', title: 'Warning', message: 'Your session will expire in 5 minutes.', delay: 2000 },
      { type: 'info', title: 'New Update', message: 'Version 2.0 is now available. Click to learn more.', delay: 3000 }
    ];

    demos.forEach(demo => {
      setTimeout(() => {
        addToast(demo.type, demo.title, demo.message);
      }, demo.delay);
    });
  }, [demoMode, addToast]);

  // PATTERN 4: Swipe gesture handling
  const handlePointerDown = React.useCallback((e, toastId) => {
    if (!enableSwipeDismiss) return;

    swipeStateRef.current[toastId] = {
      startX: e.clientX,
      currentX: e.clientX,
      isDragging: false
    };

    e.currentTarget.setPointerCapture(e.pointerId);
  }, [enableSwipeDismiss]);

  const handlePointerMove = React.useCallback((e, toastId) => {
    if (!enableSwipeDismiss) return;
    const state = swipeStateRef.current[toastId];
    if (!state) return;

    const deltaX = e.clientX - state.startX;

    if (!state.isDragging && Math.abs(deltaX) > 5) {
      state.isDragging = true;
    }

    if (state.isDragging) {
      state.currentX = e.clientX;
      const element = e.currentTarget;

      // Direct DOM manipulation for smooth drag
      if (deltaX > 0) { // Only allow right swipe
        element.style.transform = `translateX(${deltaX}px)`;
        element.style.opacity = `${Math.max(0.3, 1 - deltaX / 200)}`;
      }
    }
  }, [enableSwipeDismiss]);

  const handlePointerUp = React.useCallback((e, toastId) => {
    if (!enableSwipeDismiss) return;
    const state = swipeStateRef.current[toastId];
    if (!state || !state.isDragging) return;

    const deltaX = state.currentX - state.startX;
    const element = e.currentTarget;

    if (deltaX > swipeThreshold) {
      // Dismiss
      removeToast(toastId);
    } else {
      // Snap back
      element.style.transition = `all ${animationDuration}ms cubic-bezier(0.4, 0, 0.2, 1)`;
      element.style.transform = 'translateX(0)';
      element.style.opacity = '1';
      setTimeout(() => {
        element.style.transition = '';
      }, animationDuration);
    }

    delete swipeStateRef.current[toastId];
  }, [enableSwipeDismiss, swipeThreshold, animationDuration, removeToast]);

  // Pause/resume timer on hover
  const handleMouseEnter = React.useCallback((toastId) => {
    if (pauseOnHover && timersRef.current[toastId]) {
      clearTimeout(timersRef.current[toastId]);
    }
  }, [pauseOnHover]);

  const handleMouseLeave = React.useCallback((toast) => {
    if (pauseOnHover && toast.duration > 0) {
      const elapsed = Date.now() - toast.createdAt;
      const remaining = toast.duration - elapsed;

      if (remaining > 0) {
        timersRef.current[toast.id] = setTimeout(() => {
          removeToast(toast.id);
        }, remaining);
      }
    }
  }, [pauseOnHover, removeToast]);

  // Position styles
  const positionStyles = {
    'top-left': { top: '24px', left: '24px', alignItems: 'flex-start' },
    'top-center': { top: '24px', left: '50%', transform: 'translateX(-50%)', alignItems: 'center' },
    'top-right': { top: '24px', right: '24px', alignItems: 'flex-end' },
    'bottom-left': { bottom: '24px', left: '24px', alignItems: 'flex-start' },
    'bottom-center': { bottom: '24px', left: '50%', transform: 'translateX(-50%)', alignItems: 'center' },
    'bottom-right': { bottom: '24px', right: '24px', alignItems: 'flex-end' }
  };

  const typeColors = {
    success: config?.successColor || '#10B981',
    error: config?.errorColor || '#EF4444',
    warning: config?.warningColor || '#F59E0B',
    info: config?.infoColor || '#3B82F6'
  };

  const styles = {
    container: {
      width: '100%',
      minHeight: '100vh',
      padding: '48px 24px',
      backgroundColor: config?.backgroundColor || '#FAFAFA',
      fontFamily: config?.fontFamily || 'Inter, -apple-system, system-ui, sans-serif',
      position: 'relative'
    },
    demoControls: {
      display: demoMode ? 'flex' : 'none',
      gap: '12px',
      justifyContent: 'center',
      flexWrap: 'wrap'
    },
    demoButton: {
      padding: '12px 24px',
      fontSize: '14px',
      fontWeight: '500',
      border: 'none',
      borderRadius: config?.borderRadius || '8px',
      cursor: 'pointer',
      color: '#FFFFFF',
      transition: `all ${animationDuration}ms cubic-bezier(0.4, 0, 0.2, 1)`
    },
    toastContainer: {
      position: 'fixed',
      display: 'flex',
      flexDirection: 'column',
      gap: config?.stackGap || '12px',
      zIndex: '9999',
      pointerEvents: 'none',
      ...positionStyles[position]
    },
    toast: {
      width: config?.toastWidth || '400px',
      backgroundColor: config?.toastBackgroundColor || '#FFFFFF',
      border: `1px solid ${config?.borderColor || 'rgba(0,0,0,0.08)'}`,
      borderRadius: config?.borderRadius || '8px',
      padding: config?.toastPadding || '16px',
      boxShadow: (config?.showShadow !== false) ? '0 4px 12px rgba(0,0,0,0.1)' : 'none',
      pointerEvents: 'auto',
      touchAction: 'pan-y',
      cursor: enableSwipeDismiss ? 'grab' : 'default',
      position: 'relative',
      overflow: 'hidden',
      opacity: 0,
      transform: 'translateX(100px) scale(0.9)'
    },
    toastContent: {
      display: 'flex',
      gap: '12px',
      alignItems: 'flex-start'
    },
    icon: {
      width: '20px',
      height: '20px',
      flexShrink: '0',
      marginTop: '2px'
    },
    textContent: {
      flex: '1',
      minWidth: '0'
    },
    title: {
      fontSize: config?.titleSize || '14px',
      fontWeight: '500',
      color: config?.primaryTextColor || '#1A1A1A',
      marginBottom: '4px',
      lineHeight: '1.4'
    },
    message: {
      fontSize: config?.messageSize || '13px',
      color: config?.secondaryTextColor || '#6B6B6B',
      lineHeight: '1.5'
    },
    closeButton: {
      width: '24px',
      height: '24px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      backgroundColor: 'transparent',
      border: 'none',
      borderRadius: '4px',
      cursor: 'pointer',
      color: config?.secondaryTextColor || '#6B6B6B',
      flexShrink: '0',
      marginTop: '2px',
      transition: `all ${animationDuration}ms cubic-bezier(0.4, 0, 0.2, 1)`
    },
    progressBar: {
      position: 'absolute',
      bottom: '0',
      left: '0',
      right: '0',
      height: '3px',
      backgroundColor: 'rgba(0,0,0,0.1)',
      overflow: 'hidden',
      display: showProgressBar ? 'block' : 'none'
    },
    progressFill: {
      height: '100%',
      backgroundColor: 'currentColor',
      transformOrigin: 'left',
      animation: `progress ${defaultDuration}ms linear forwards`
    }
  };

  // PATTERN 1: Entrance animation for new toasts
  React.useEffect(() => {
    const lastToast = toasts[0];
    if (!lastToast) return;

    const element = document.querySelector(`[data-toast-id="${lastToast.id}"]`);
    if (element && element.style.opacity === '0') {
      requestAnimationFrame(() => {
        element.animate([
          { opacity: 0, transform: 'translateX(100px) scale(0.9)' },
          { opacity: 1, transform: 'translateX(0) scale(1)' }
        ], {
          duration: animationDuration,
          easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
          fill: 'forwards'
        });
      });
    }
  }, [toasts, animationDuration]);

  const getIcon = (type) => {
    const color = typeColors[type];

    switch(type) {
      case 'success':
        return (
          <svg style={{...styles.icon, color}} viewBox="0 0 20 20" fill="none">
            <circle cx="10" cy="10" r="9" fill="currentColor" opacity="0.2" />
            <path d="M6 10l3 3 5-6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        );
      case 'error':
        return (
          <svg style={{...styles.icon, color}} viewBox="0 0 20 20" fill="none">
            <circle cx="10" cy="10" r="9" fill="currentColor" opacity="0.2" />
            <path d="M7 7l6 6M13 7l-6 6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
