      case 'warning':
        return (
          <svg style={{...styles.icon, color}} viewBox="0 0 20 20" fill="none">
            <path d="M10 2L2 17h16L10 2z" fill="currentColor" opacity="0.2" />
            <path d="M10 8v4M10 14v.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          </svg>
        );
      case 'info':
        return (
          <svg style={{...styles.icon, color}} viewBox="0 0 20 20" fill="none">
            <circle cx="10" cy="10" r="9" fill="currentColor" opacity="0.2" />
            <path d="M10 10v4M10 6v.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          </svg>
        );
      default:
        return null;
    }
