      )}

      <div style={styles.toastContainer}>
        {toasts.map((toast) => (
          <div
            key={toast.id}
            data-toast-id={toast.id}
            style={styles.toast}
            onPointerDown={(e) => handlePointerDown(e, toast.id)}
            onPointerMove={(e) => handlePointerMove(e, toast.id)}
            onPointerUp={(e) => handlePointerUp(e, toast.id)}
            onPointerCancel={(e) => handlePointerUp(e, toast.id)}
            onMouseEnter={() => handleMouseEnter(toast.id)}
            onMouseLeave={() => handleMouseLeave(toast)}
          >
            <div style={styles.toastContent}>
              {getIcon(toast.type)}
              <div style={styles.textContent}>
                <div style={styles.title}>{toast.title}</div>
                <div style={styles.message}>{toast.message}</div>
              </div>
              <button
                style={styles.closeButton}
                onClick={() => removeToast(toast.id)}
                onMouseEnter={(e) => e.currentTarget.style.backgroundColor = 'rgba(0,0,0,0.05)'}
                onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'transparent'}
                aria-label="Close notification"
              >
                <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                  <path d="M4 4l8 8M12 4l-8 8" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                </svg>
              </button>
            </div>
            {showProgressBar && toast.duration > 0 && (
              <div style={styles.progressBar}>
                <div style={{...styles.progressFill, color: typeColors[toast.type]}} />
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

